from itertools import permutations

def standard_cyclic_representation(perm):
    n = len(perm)
    visited = [False] * n
    cycles = []

    for i in range(n):
        if not visited[i]:
            cycle = []
            x = i
            while not visited[x]:
                visited[x] = True
                cycle.append(x + 1)
                x = perm[x] - 1
            if cycle:
                cycles.append(cycle)

    for cycle in cycles:
        if len(cycle) > 1:
            max_val = max(cycle)
            cycle_index = cycle.index(max_val)
            cycle[:] = cycle[cycle_index:] + cycle[:cycle_index]

    cycles.sort()
    result = []
    for cycle in cycles:
        result.extend(cycle)
    return result

def find_kth_permutation(n, k):
    perms = list(permutations(range(1, n + 1)))
    sorted_perms = sorted(perms)
    return sorted_perms[k - 1]

def main():
    n, k = map(int, input().split())
    perm = find_kth_permutation(n, k)
    print(*perm)

if __name__ == "__main__":
    main()
